create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'staff' check(role in ('admin','staff')), created_at timestamptz not null default now());
create table public.teachers (id uuid primary key default gen_random_uuid(), employee_id text not null unique, full_name text not null, email text, phone text, subject text, qualification text, joining_date date, monthly_salary numeric(12,2) not null default 0, working_hours numeric(4,2) not null default 8, status text not null default 'active' check(status in ('active','inactive')), face_descriptor jsonb, face_enrolled boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.attendance (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.teachers(id), attendance_date date not null, in_time timestamptz, out_time timestamptz, status text not null default 'present' check(status in ('present','absent','half_day','paid_leave','unpaid_leave')), verification_method text check(verification_method in ('face','manual')), manually_modified_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(teacher_id,attendance_date));
create table public.teacher_notes (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.teachers(id), note text not null check(char_length(note)>0), created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.payroll (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.teachers(id), month int not null check(month between 1 and 12), year int not null check(year between 2020 and 2100), monthly_salary numeric(12,2) not null, working_days numeric(5,2) not null, present_days numeric(5,2) not null default 0, half_days numeric(5,2) not null default 0, paid_leave_days numeric(5,2) not null default 0, unpaid_leave_days numeric(5,2) not null default 0, gross_salary numeric(12,2) not null, deductions numeric(12,2) not null, net_salary numeric(12,2) not null, status text not null default 'draft' check(status in ('draft','finalized','paid')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(teacher_id,month,year));
create index teachers_employee_id_idx on public.teachers(employee_id); create index attendance_teacher_date_idx on public.attendance(teacher_id,attendance_date); create index teacher_notes_teacher_idx on public.teacher_notes(teacher_id); create index payroll_teacher_month_year_idx on public.payroll(teacher_id,month,year);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger teachers_updated before update on public.teachers for each row execute function public.set_updated_at(); create trigger attendance_updated before update on public.attendance for each row execute function public.set_updated_at(); create trigger notes_updated before update on public.teacher_notes for each row execute function public.set_updated_at(); create trigger payroll_updated before update on public.payroll for each row execute function public.set_updated_at();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
alter table public.profiles enable row level security; alter table public.teachers enable row level security; alter table public.attendance enable row level security; alter table public.teacher_notes enable row level security; alter table public.payroll enable row level security;
create policy "profile self read" on public.profiles for select to authenticated using(id=auth.uid());
create policy "admin teachers" on public.teachers for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admin attendance" on public.attendance for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admin notes" on public.teacher_notes for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "admin payroll" on public.payroll for all to authenticated using(public.is_admin()) with check(public.is_admin());
-- After creating the first auth user: insert into public.profiles(id,role) values ('AUTH_USER_UUID','admin') on conflict(id) do update set role='admin';
